/* ---------------- HELPERS ---------------- */
const extByLang = (lang = "") => {
  switch (lang.toLowerCase()) {
    case "java": return "java";
    case "c": return "c";
    case "cpp":
    case "c++": return "cpp";
    case "python":
    case "py": return "py";
    case "javascript":
    case "js": return "js";
    default: return "txt";
  }
};

export default function ProgramPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const prog = allPrograms[id];

  const [showToast, setShowToast] = useState(null); // message string
  const [wrap, setWrap] = useState(false);
  const [lineNos, setLineNos] = useState(true);
  const [fontSize, setFontSize] = useState(15);
  const [fullscreen, setFullscreen] = useState(false);

  const codeRef = useRef(null);

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [id]);

  useEffect(() => {
    const onKey = (e) => {
      if (!prog) return;
      if (e.key === "c") { e.preventDefault(); copyCode(); }
      if (e.key === "d") { e.preventDefault(); downloadFile(); }
      if (e.key === "w") { e.preventDefault(); setWrap(v => !v); }
      if (e.key === "l") { e.preventDefault(); setLineNos(v => !v); }
      if (e.key === "=" || e.key === "+") { e.preventDefault(); setFontSize(f => Math.min(24, f + 1)); }
      if (e.key === "-") { e.preventDefault(); setFontSize(f => Math.max(10, f - 1)); }
      if (e.key === "f") { e.preventDefault(); setFullscreen(v => !v); }
      if (e.key === "Escape" && fullscreen) { setFullscreen(false); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [prog, fullscreen]);

  const show = useCallback((msg) => {
    setShowToast(msg);
    const t = setTimeout(() => setShowToast(null), 1600);
    return () => clearTimeout(t);
  }, []);

  const copyCode = useCallback(() => {
    if (!prog) return;
    navigator.clipboard.writeText(prog.code);
    show("Copied to clipboard");
  }, [prog, show]);

  const downloadFile = useCallback(() => {
    if (!prog) return;
    const ext = extByLang(prog.lang);
    const blob = new Blob([prog.code], { type: "text/plain;charset=utf-8" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `program${prog.id}.${ext}`;
    link.click();
    show("File downloaded");
  }, [prog, show]);

  const onButtonMove = (e) => {
    const target = e.currentTarget;
    const r = target.getBoundingClientRect();
    const mx = ((e.clientX - r.left) / r.width) * 100;
    const my = ((e.clientY - r.top) / r.height) * 100;
    target.style.setProperty("--mx", `${mx}%`);
    target.style.setProperty("--my", `${my}%`);
  };

  if (!prog) return <p style={{ color: "#aaa", padding: 16 }}>Program not found.</p>;

  const CodeBlock = (
    <CodeShell>
      <CodeHeader>
        <CodeMeta>
          <span className="pill">#{prog.id}</span>
          <span className="pill">{(prog.lang || "text").toUpperCase()}</span>
        </CodeMeta>
        <Toolbar>
          <Button onMouseMove={onButtonMove} onClick={copyCode}><FiCopy /> Copy <kbd style={{opacity:.6}}>C</kbd></Button>
          <Button onMouseMove={onButtonMove} onClick={downloadFile}><FiDownload /> Download <kbd style={{opacity:.6}}>D</kbd></Button>
          <Button onMouseMove={onButtonMove} onClick={() => setWrap(v => !v)}><FiWrapText /> {wrap ? "Unwrap" : "Wrap"} <kbd style={{opacity:.6}}>W</kbd></Button>
          <Button onMouseMove={onButtonMove} onClick={() => setLineNos(v => !v)}><FiHash /> {lineNos ? "Hide #": "Show #"} <kbd style={{opacity:.6}}>L</kbd></Button>
          <Button onMouseMove={onButtonMove} onClick={() => setFontSize(f => Math.max(10, f - 1))}><FiType /> A- <kbd style={{opacity:.6}}>-</kbd></Button>
          <Button onMouseMove={onButtonMove} onClick={() => setFontSize(f => Math.min(24, f + 1))}><FiType /> A+ <kbd style={{opacity:.6}}>=</kbd></Button>
          <Button onMouseMove={onButtonMove} onClick={() => setFullscreen(v => !v)}>
            {fullscreen ? <FiMinimize /> : <FiMaximize />} {fullscreen ? "Exit" : "Full"} <kbd style={{opacity:.6}}>F</kbd>
          </Button>
        </Toolbar>
      </CodeHeader>

      <CodeWrapper ref={codeRef}>
        <SyntaxHighlighter
          language={prog.lang}
          style={tomorrowNight}
          showLineNumbers={lineNos}
          wrapLines={wrap}
          customStyle={{
            minWidth: wrap ? "auto" : "640px",
            fontSize: `${fontSize}px`,
            padding: "16px 18px",
            background: "transparent",
          }}
          lineNumberStyle={{ opacity: 0.6 }}
        >
          {prog.code}
        </SyntaxHighlighter>
      </CodeWrapper>
    </CodeShell>
  );

  return (
    <>
      <Global />
      {showToast && (
        <Toast><FiCheck /> {showToast}</Toast>
      )}

      {fullscreen ? (
        <FullScreen onKeyDown={(e)=> e.key === "Escape" && setFullscreen(false)}>
          <div style={{display:"flex", alignItems:"center", gap:10, marginBottom:10}}>
            <BackButton onClick={() => setFullscreen(false)}><FiMinimize /> Exit full-screen</BackButton>
            <Title style={{marginLeft:6}}>{prog.title}</Title>
          </div>
          <div style={{flex:1, minHeight:0, overflow:"auto"}}>{CodeBlock}</div>
        </FullScreen>
      ) : (
        <Page>
          <StickyBar>
            <BackButton onClick={() => navigate("/")}><FiArrowLeft /> Back</BackButton>
            <Title>{prog.title}</Title>
          </StickyBar>

          <div style={{animation: `${fadeIn} .4s ease both`}}>
            {CodeBlock}
          </div>
        </Page>
      )}
    </>
  );
}
